<?php require __DIR__.'/includes/auth.php';$p=db();
$p->exec("CREATE TABLE IF NOT EXISTS gallery_page_settings (id TINYINT UNSIGNED NOT NULL PRIMARY KEY, hero_kicker VARCHAR(120) NOT NULL DEFAULT 'PHOTO GALLERY', hero_title VARCHAR(255) NOT NULL DEFAULT 'FEEL THE', hero_accent VARCHAR(120) NOT NULL DEFAULT 'ADRENALINE.', hero_description TEXT NULL, hero_image VARCHAR(500) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("INSERT IGNORE INTO gallery_page_settings (id) VALUES (1)");
if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();if(($_POST['act']??'')==='save_header'){$q=$p->query('SELECT hero_image FROM gallery_page_settings WHERE id=1');$oldHero=$q->fetchColumn();$heroImage=admin_upload('hero_image','gallery-hero',$oldHero);$p->prepare('UPDATE gallery_page_settings SET hero_kicker=?,hero_title=?,hero_accent=?,hero_description=?,hero_image=? WHERE id=1')->execute([trim($_POST['hero_kicker']??''),trim($_POST['hero_title']??''),trim($_POST['hero_accent']??''),trim($_POST['hero_description']??''),$heroImage]);header('Location: gallery.php');exit;}if($_POST['act']==='save'){$path=admin_upload('image','gallery');$p->prepare('INSERT INTO gallery(title,image_path,alt_text,category,sort_order,status) VALUES(?,?,?,?,?,?)')->execute([$_POST['title'], $path,$_POST['alt_text'],$_POST['category'],(int)$_POST['sort_order'],isset($_POST['status'])?(int)$_POST['status']:1]);header('Location: gallery.php');exit;}if($_POST['act']==='delete'){$q=$p->prepare('SELECT image_path FROM gallery WHERE id=?');$q->execute([(int)$_POST['id']]);admin_delete_image($q->fetchColumn());$p->prepare('DELETE FROM gallery WHERE id=?')->execute([(int)$_POST['id']]);header('Location: gallery.php');exit;}}$rows=$p->query('SELECT * FROM gallery ORDER BY sort_order,id DESC')->fetchAll();$hero=$p->query('SELECT * FROM gallery_page_settings WHERE id=1 LIMIT 1')->fetch() ?: [];$page_title='Gallery';require __DIR__.'/includes/header.php';?>
<div class="form" style="margin-bottom:20px"><div class="head"><h2>Gallery Page Header</h2></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="save_header"><div class="formgrid"><div class="field"><label>Hero Kicker</label><input name="hero_kicker" value="<?=admin_e($hero['hero_kicker']??'PHOTO GALLERY')?>"></div><div class="field"><label>Hero Title</label><input name="hero_title" value="<?=admin_e($hero['hero_title']??'FEEL THE')?>"></div><div class="field"><label>Hero Accent</label><input name="hero_accent" value="<?=admin_e($hero['hero_accent']??'ADRENALINE.')?>"></div><div class="field full"><label>Hero Description</label><textarea name="hero_description"><?=admin_e($hero['hero_description']??'A glimpse of the landscapes, tracks, and outdoor moments that inspire every Bali Tarantula expedition.')?></textarea></div><div class="field full"><label>Hero Background Image</label><input type="file" name="hero_image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($hero['hero_image'])):?><small class="muted-line">Current: <?=admin_e($hero['hero_image'])?></small><?php endif;?></div></div><div class="actions"><button class="btn">Save Header</button></div></form></div>
